#!/usr/bin/env Rscript
suppressPackageStartupMessages({library(ggplot2); library(patchwork); library(corrplot); library(ComplexHeatmap); library(circlize); library(linkET); library(Hmisc); library(dplyr); library(ggridges); library(sf); library(rnaturalearth); library(scatterpie); library(ggh4x)})
out <- "results/learning_validation/batch3"
dir.create(file.path(out,"figures"), recursive=TRUE, showWarnings=FALSE)
set.seed(8417)
save <- function(p,id,w,h) ggsave(file.path(out,"figures",paste0("SCICASE-",id,"-redraw.png")),p,width=w,height=h,dpi=180,bg="white")
theme_set(theme_classic(base_size=9))
# 014 corrplot: upper square matrix, significance blanks and ordered group bars
x <- matrix(rnorm(240), ncol=12); colnames(x)<-paste0("V",1:12); corx<-cor(x); diag(corx)<-1
p014d<-expand.grid(i=1:12,j=1:12); p014d$r<-corx[cbind(p014d$j,p014d$i)]; p014d<-subset(p014d,i<j); p014<-ggplot(p014d,aes(i,j,fill=r))+geom_tile(color="white",linewidth=.35)+geom_text(aes(label=ifelse(abs(r)>.28,sprintf("%.1f",r),"")),size=2)+scale_fill_gradient2(low="#2864A5",mid="white",high="#C94D63",limits=c(-1,1))+scale_x_continuous(breaks=1:12,labels=colnames(x),position="top",expand=c(0,0))+scale_y_continuous(breaks=1:12,labels=colnames(x),expand=c(0,0))+coord_equal()+labs(x=NULL,y=NULL,fill="r")+theme(axis.text.x=element_text(angle=45,hjust=0),axis.ticks=element_blank(),panel.border=element_rect(fill=NA,color="grey25",linewidth=.45),panel.grid=element_blank())
save(p014,"014",7.2,6.6)
# 017 ComplexHeatmap two triangles, same diverging scale and group strip
m<-cor(matrix(rnorm(360),ncol=12)); diag(m)<-NA; grp<-rep(c("A","B","C"),each=4); m[upper.tri(m)]<-m[upper.tri(m)]*.75
png(file.path(out,"figures","SCICASE-017-redraw.png"),width=761,height=800,res=120); ht<-Heatmap(m,name="r",col=colorRamp2(c(-1,0,1),c("#3478A8","white","#D65F5F")),cluster_rows=FALSE,cluster_columns=FALSE,rect_gp=gpar(col="grey70",lwd=.35),row_split=grp,column_split=grp,show_row_names=TRUE,show_column_names=TRUE,row_names_gp=gpar(fontsize=7),column_names_gp=gpar(fontsize=7),column_names_rot=45); draw(ht); dev.off()
# 031 linkET: correlation tiles and Mantel-like curved links, size/p mapping
env<-as.data.frame(matrix(rnorm(120),ncol=6,dimnames=list(NULL,paste0("E",1:6)))); envcor<-cor(env); links<-expand.grid(from=1:4,to=1:6); links$r<-runif(nrow(links),.08,.38); links$p<-sample(c("<0.05",">=0.05"),nrow(links),TRUE)
p031<-ggplot()+geom_tile(data=expand.grid(i=1:6,j=1:6),aes(i,j,fill=envcor[cbind(j,i)]),color="white",linewidth=.3)+scale_fill_gradient2(low="#F08A62",mid="white",high="#54AFC1",limits=c(-1,1))+geom_curve(data=links,aes(x=links$from*.72,y=links$to,xend=7.4,yend=links$from,linewidth=r,color=p),curvature=.18,alpha=.75)+scale_linewidth(range=c(.35,1.1))+scale_color_manual(values=c("<0.05"="#3C86B5",">=0.05"="grey65"))+scale_x_continuous(breaks=1:6,labels=names(env),position="top",limits=c(.5,8))+scale_y_reverse(breaks=1:6,labels=names(env),limits=c(6.5,.5))+coord_equal(clip="off")+labs(x=NULL,y=NULL,fill="Pearson r",linewidth="Mantel r",color="Mantel p")+theme(axis.text.x=element_text(angle=45,hjust=0),axis.ticks=element_blank(),panel.grid=element_blank(),plot.margin=margin(15,45,15,15))
save(p031,"031",7.2,4.7)
# 082 butterfly stacked bars: left/right mirror, central category labels
cats<-paste("Type",LETTERS[1:9]); dd<-expand.grid(type=cats,resp=c("Risk","Protective"),side=c("PFS","OS")); dd$value<-runif(nrow(dd),1,15); dd$val<-ifelse(dd$side=="PFS",-dd$value,dd$value)
p082<-ggplot(dd,aes(val,factor(type,levels=rev(cats)),fill=resp))+geom_col(width=.72,color="grey20",linewidth=.28)+geom_vline(xintercept=0,linewidth=.5)+facet_grid(.~side,scales="free_x",space="free_x",labeller=as_labeller(c(PFS="PFS",OS="OS")))+scale_fill_manual(values=c(Risk="#B33C44",Protective="#4F94B9"))+scale_x_continuous(labels=abs,expand=expansion(mult=c(.04,.04)))+labs(x="Number of cancer types",y=NULL,fill=NULL)+theme(strip.background=element_blank(),strip.text=element_text(face="bold"),axis.text.y=element_text(size=7),panel.grid=element_blank(),legend.position="bottom",panel.border=element_rect(fill=NA,color="grey35",linewidth=.45))
save(p082,"082",7.2,6)
# 085 four independent time-course panels with SD ribbons
t<-seq(-10,20,length.out=61); ts<-do.call(rbind,lapply(1:4,function(k)data.frame(time=t,mean=3.82+k*.035+sin(t/4+k)*.04,sd=.018+k*.003,panel=paste0("S",k),col=c("#7813F3","#188A8A","#E58A29","#CF5A82")[k])))
ps<-lapply(1:4,function(k){z<-subset(ts,panel==paste0("S",k)); ggplot(z,aes(time,mean))+geom_ribbon(aes(ymin=mean-sd,ymax=mean+sd),fill=z$col[1],alpha=.22)+geom_line(color=z$col[1],linewidth=.65)+scale_x_continuous(limits=c(-10,20),breaks=seq(-10,20,10),expand=c(0,0))+labs(x=NULL,y=paste0("Signal ",k))+theme_classic(base_size=8)+theme(axis.text=element_text(size=7))}); save(wrap_plots(ps,nrow=1),"085",8,2.4)
# 089 world map with location pies and size-scaled markers
world<-ne_countries(scale="medium",returnclass="sf") |> filter(region_un!="Antarctica"); set.seed(89); sites<-data.frame(lon=runif(18,-155,155),lat=runif(18,-48,68),a=runif(18,1,8),b=runif(18,1,8),c=runif(18,1,8)); sites$r<-4+log10(rowSums(sites[,3:5]))*2
p089<-ggplot()+geom_sf(data=world,fill="white",color="grey72",linewidth=.22)+geom_scatterpie(data=sites,aes(x=lon,y=lat,r=r),cols=c("a","b","c"),alpha=.82,color="white",linewidth=.18)+scale_fill_manual(values=c("#0A8066","#E23A2C","#E2B532"))+coord_sf(xlim=c(-180,180),ylim=c(-58,82),expand=FALSE)+labs(fill=NULL)+theme_void()+theme(panel.background=element_rect(fill="#DDECF0",color=NA),legend.position="right",legend.text=element_text(size=7),legend.key.size=unit(.28,"cm"))
save(p089,"089",8,4.45)
# 135 grouped observations, quadratic fit, group means with asymmetric visual layers
dat<-do.call(rbind,lapply(1:5,function(g){xx<-runif(18,2.32,2.44); data.frame(x=xx,y=150+g*70+1300*(xx-2.32)+rnorm(18,0,55),g=factor(g))})); sm<-aggregate(cbind(x,y)~g,dat,mean); sm$sx<-aggregate(x~g,dat,sd)$x;sm$sy<-aggregate(y~g,dat,sd)$y
p135<-ggplot(dat,aes(x,y,color=g))+geom_point(size=1.8,alpha=.8)+geom_smooth(aes(group=1),method="lm",formula=y~poly(x,2),se=FALSE,color="black",linewidth=.55,linetype=2)+geom_errorbar(data=sm,aes(x=x,ymin=y-sy,ymax=y+sy),inherit.aes=FALSE,width=.0008,linewidth=.42,color="grey25")+geom_errorbar(data=sm,aes(y=y,xmin=x-sx,xmax=x+sx),inherit.aes=FALSE,width=9,orientation="y",linewidth=.42,color="grey25")+geom_point(data=sm,aes(x,y),inherit.aes=FALSE,shape=18,size=3.2,color="black")+scale_color_manual(values=c("#4C9DCA","#89CAF0","#4EBB9E","#EFBB4D","#E28F4D"))+scale_x_continuous(breaks=seq(2.32,2.44,.04),sec.axis=dup_axis())+scale_y_continuous(breaks=seq(0,800,200),sec.axis=dup_axis())+labs(x="Energy (eV)",y="Lifetime (ps)",color="Group")+theme_bw(base_size=9)+theme(panel.grid=element_blank(),axis.text=element_text(size=8,color="black"),legend.position=c(.03,.97),legend.justification=c(0,1),legend.title=element_blank())
save(p135,"135",7.2,6.2)
# 149 density ridges + aligned diverging count bars, shared genus order
gn<-paste0("G",1:18); z<-do.call(rbind,lapply(seq_along(gn),function(i)data.frame(genus=gn[i],value=rnorm(12,0,.012)+sin(i/3)*.012))); z$genus<-factor(z$genus,levels=rev(gn)); z$dir<-ifelse(z$value>=0,"Positive","Negative"); write.csv(z,file.path(out,"plot_data","SCICASE-149-simulated.csv"),row.names=FALSE)
rp<-ggplot(z,aes(value,genus,fill=after_stat(x)))+geom_density_ridges_gradient(scale=1.05,rel_min_height=.01,color="grey35",linewidth=.18)+scale_fill_gradientn(colors=c("#2E7AB8","white","#80D3A9"),guide="none")+scale_x_continuous(limits=c(-.045,.06),breaks=seq(-.03,.06,.03),expand=c(0,0))+labs(x=expression(beta[1]*" (MAG)"),y=NULL)+theme_classic(base_size=8)+theme(axis.text.y=element_blank(),axis.ticks.y=element_blank())
counts<-as.data.frame(table(z$genus,z$dir));names(counts)<-c("genus","dir","n");counts$n<-as.numeric(counts$n);counts$n<-ifelse(counts$dir=="Negative",-counts$n,counts$n); bp<-ggplot(counts,aes(n,genus,fill=dir))+geom_col(color="grey25",linewidth=.15,width=.72)+geom_vline(xintercept=0,linewidth=.4)+scale_fill_manual(values=c(Negative="#2E7AB8",Positive="#80D3A9"))+scale_x_continuous(limits=c(-20,12),breaks=seq(-20,10,5),labels=abs,expand=c(0,0))+labs(x="Number of MAGs",y=NULL)+theme_classic(base_size=8)+theme(axis.text.y=element_blank(),axis.ticks.y=element_blank(),legend.position="none")
save(rp+bp+plot_layout(widths=c(3,2)),"149",8,7)
# 027 pair matrix: package panel grammar from the Python source translated into GGally panels.
suppressPackageStartupMessages(library(GGally))
dat27<-as.data.frame(matrix(rnorm(7*320),ncol=7)); names(dat27)<-LETTERS[1:7]; C27<-matrix(c(1,.6,.25,.1,.05,.18,.22,.6,1,.48,.08,.2,.14,.05,.25,.48,1,.4,.15,.1,.2,.1,.08,.4,1,.52,.16,.3,.05,.2,.15,.52,1,.45,.2,.18,.14,.1,.16,.45,1,.55,.22,.05,.2,.3,.2,.55,1),7,7); U<-chol(C27); dat27<-as.data.frame(as.matrix(dat27)%*%U); names(dat27)<-LETTERS[1:7]; write.csv(dat27,file.path(out,"plot_data","SCICASE-027-simulated.csv"),row.names=FALSE)
upper_corr<-function(data,mapping,...){xx<-GGally::eval_data_col(data,mapping$x); yy<-GGally::eval_data_col(data,mapping$y); r<-cor(xx,yy); ggplot(data.frame(x=.5,y=.5,r=r),aes(x,y,fill=r))+geom_tile()+geom_text(aes(label=sprintf("%.2f",r)),size=2.5)+scale_fill_gradientn(colours=c("#00007F","#0000FF","#00FFFF","#00FF00","#FFFF00","#FF7F00","#FF0000","#7F0000"),limits=c(-1,1))+theme_void()+theme(legend.position="none")}
lower_kde<-function(data,mapping,...){ggplot(data,mapping)+stat_density_2d(aes(fill=after_stat(level)),geom="polygon",contour=TRUE,alpha=.82)+scale_fill_gradientn(colours=c("#FFFFFF","#17BECF","#1F77B4","#2CA02C","#FFFF00","#FF7F0E","#D62728","#8B0000"))+theme_test(base_size=6)+theme(axis.text=element_text(size=5),axis.title=element_blank(),legend.position="none")}
p027<-GGally::ggpairs(dat27,upper=list(continuous=upper_corr),lower=list(continuous=lower_kde),diag=list(continuous=GGally::wrap("densityDiag",fill="#7DAFBD",alpha=.7)))+theme(strip.text=element_blank(),panel.spacing=unit(.5,"mm")); ggsave(file.path(out,"figures","SCICASE-027-redraw.png"),p027,width=7.4,height=6.3,dpi=180,bg="white")
# 096 inferential workflow using base stats; preserve grouping, patterned bars, replicate marks.
dat96<-expand.grid(Group=c("Vehicle","Glu-CA","Glu-CDCA"),Treatment=c("T0","T1","T2"),rep=1:5); gi<-match(dat96$Group,c("Vehicle","Glu-CA","Glu-CDCA"))-1; ti<-match(dat96$Treatment,c("T0","T1","T2"))-1; dat96$value<-pmax(.12,rnorm(nrow(dat96),1.05+gi*.42+ti*.32+gi*ti*.12,.16)); dat96$condition<-interaction(dat96$Group,dat96$Treatment,sep="-"); write.csv(dat96,file.path(out,"plot_data","SCICASE-096-simulated.csv"),row.names=FALSE); fit96<-aov(value~condition,data=dat96); capture.output(summary(fit96),file=file.path(out,"tables","SCICASE-096-anova.txt")); capture.output(TukeyHSD(fit96),file=file.path(out,"tables","SCICASE-096-tukey.txt")); ss<-aggregate(value~Group+Treatment,dat96,function(v)c(mean=mean(v),se=sd(v)/sqrt(length(v)))); ss<-data.frame(Group=ss$Group,Treatment=ss$Treatment,mean=ss$value[,1],se=ss$value[,2]); ss$x<-seq_len(nrow(ss))*.62+rep(c(0,.42,.84),each=3); ss$fill<-c("#7b7d7f","#bd8f31","#6da94e")[match(ss$Group,c("Vehicle","Glu-CA","Glu-CDCA"))]
p096<-ggplot()+geom_col(data=ss,aes(x,mean,fill=Group),width=.4,color="black",linewidth=.6)+geom_errorbar(data=ss,aes(x,ymin=mean-se,ymax=mean+se),width=.09,linewidth=.55)+geom_point(data=dat96,aes(x=ss$x[match(condition,unique(condition))]+runif(nrow(dat96),-.07,.07),y=value,color=Group),inherit.aes=FALSE,size=1.35,position="identity")+scale_fill_manual(values=c("Vehicle"="#7b7d7f","Glu-CA"="#bd8f31","Glu-CDCA"="#6da94e"))+scale_color_manual(values=c("Vehicle"="#66686A","Glu-CA"="#A77B25","Glu-CDCA"="#548B3D"))+scale_x_continuous(breaks=ss$x,labels=ss$Treatment,expand=expansion(add=c(.3,.3)))+coord_cartesian(ylim=c(0,3.2),clip="off")+labs(x=NULL,y="Response (a.u.)",fill=NULL,color=NULL,title="Group × treatment response")+theme_classic(base_size=9)+theme(axis.text.x=element_text(angle=40,hjust=1),legend.position="right",plot.margin=margin(8,35,8,8)); ggsave(file.path(out,"figures","SCICASE-096-redraw.png"),p096,width=6.3,height=5.2,dpi=180,bg="white")
